<?php require_once __DIR__.'/../../config/seguranca.php';exigirAdmin();require_once __DIR__.'/../../includes/funcoes.php';require_once __DIR__.'/../../config/conexao.php';if($_SERVER['REQUEST_METHOD']!=='POST'||!validarCsrf(post('csrf')))redirect('admin/produtos/index.php');$id=(int)post('id');if($id<=0)redirect('admin/produtos/index.php');$pdo=getPDO();try{$st=$pdo->prepare('SELECT imagem FROM produtos WHERE id=?');$st->execute([$id]);$image=$st->fetchColumn();$pdo->prepare('DELETE FROM produtos WHERE id=?')->execute([$id]);limparUpload($image);flash('sucesso','Produto excluído.');}catch(Throwable $e){flash('erro','Não foi possível excluir. Se o produto já estiver em pedidos, desative-o em vez de excluir.');}redirect('admin/produtos/index.php');
